    const ML2_Scalar *restrict linearGradientPtr = (const ML2_Scalar *)ML2_DeviceDataAsCUDA(linearGradient.data).ptr;
    ML2_Scalar *restrict decayingSumPtr = (ML2_Scalar *)ML2_DeviceDataAsCUDA(decayingSum.data).ptr;
    ML2_Scalar *restrict decayingSquareSumPtr = (ML2_Scalar *)ML2_DeviceDataAsCUDA(decayingSquareSum.data).ptr;

    constexpr ML2_Int blockDimX = 256;
