#ifdef ML2_CUDA_ENABLE
        case ML2_DeviceCUDA: ML2_CUDA_BiasesAdamWOptimize(biases, biasesGradient, decayingSum, decayingSquareSum, learningRate, decayRate1, decayRate2, decayingWeight1, decayingWeight2, parameterDecay); break;
#endif // ML2_CUDA_ENABLE
